package local.tvmorph.tv;
import android.app.*;import android.os.*;import android.content.*;import android.media.*;import android.webkit.*;import org.json.*;import java.io.*;import java.util.*;
public class RadioActivity extends Activity {
 static volatile RadioActivity active;private WebView web;private int keyboardRequest;private boolean keyboardShown;private JSONArray stations;private RadioPlayback playback;private final RadioPlayback.Listener playbackListener=(id,state,message)->js("if(window.RadioUI)RadioUI.restore("+playback.status().toString()+")");
 static JSONArray catalog(Context c)throws Exception{try(InputStream in=c.getAssets().open("radio/stations.json")){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return new JSONArray(out.toString("UTF-8"));}}
 private String t(String ar,String en){return UiSettings.text(this,ar,en);}private String name(JSONObject s){return t(s.optString("name"),s.optString("nameEn"));}
 @Override public void onCreate(Bundle state){super.onCreate(state);overridePendingTransition(0,0);getWindow().setSoftInputMode(android.view.WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_HIDDEN|android.view.WindowManager.LayoutParams.SOFT_INPUT_ADJUST_NOTHING);playback=RadioPlayback.get(this);try{stations=catalog(this);}catch(Exception e){stations=new JSONArray();}web=new WebView(this){@Override public boolean onKeyPreIme(int code,android.view.KeyEvent event){if(code==android.view.KeyEvent.KEYCODE_BACK&&keyboardShown){if(event.getAction()==android.view.KeyEvent.ACTION_UP)js("if(window.RadioNavigation)RadioNavigation.closeKeyboard();");return true;}return super.onKeyPreIme(code,event);}};web.setBackgroundColor(0xff07101e);web.setVisibility(android.view.View.INVISIBLE);setContentView(web);PageFirstFrame.awaitVisible(this,web);WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setUseWideViewPort(true);s.setSupportZoom(false);s.setBuiltInZoomControls(false);s.setDisplayZoomControls(false);s.setTextZoom(100);s.setLoadWithOverviewMode(true);s.setAllowFileAccess(false);s.setAllowContentAccess(false);s.setAllowUniversalAccessFromFileURLs(true);s.setMediaPlaybackRequiresUserGesture(false);web.addJavascriptInterface(new Bridge(),"RadioNative");web.setWebViewClient(new WebViewClient(){
 // Reveal one committed frame after the local page and its artwork finish.
 // A new Activity must not expose partially painted WebView tiles on entry.
 @Override public void onPageFinished(WebView view,String url){view.postVisualStateCallback(1,new WebView.VisualStateCallback(){@Override public void onComplete(long requestId){if(!isFinishing()&&web==view)view.setVisibility(android.view.View.VISIBLE);}});}
@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return true;}@Override public void onReceivedSslError(WebView v,SslErrorHandler h,android.net.http.SslError e){h.cancel();}});web.loadUrl("file:///android_asset/radio/index.html");}
 private void startAlternate(String id){if(active==this&&!isFinishing()&&ParentalTimer.allow(this,"local.tvmorph.tv.radio"))playback.playAlternate(id);}
 private void js(String expression){if(web!=null)web.evaluateJavascript(expression,null);} public final class Bridge{
 @JavascriptInterface public void hideKeyboard(){runOnUiThread(()->{keyboardRequest++;keyboardShown=false;if(web!=null)((android.view.inputmethod.InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(web.getWindowToken(),0);});}
 @JavascriptInterface public void showKeyboard(String id,String value){if(!"station-search".equals(id))return;runOnUiThread(()->{if(web==null||isFinishing())return;final int serial=++keyboardRequest;web.evaluateJavascript("(function(){var e=document.getElementById('station-search');return !!(e&&document.activeElement===e&&!e.readOnly);})()",ready->{if("true".equals(ready)&&serial==keyboardRequest&&web!=null&&!isFinishing()){web.requestFocus();web.postDelayed(()->{if(serial==keyboardRequest&&web!=null&&!isFinishing()){keyboardShown=true;((android.view.inputmethod.InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).showSoftInput(web,android.view.inputmethod.InputMethodManager.SHOW_IMPLICIT);}},80);}});});}
  @JavascriptInterface public int volume(){AudioManager audio=(AudioManager)getSystemService(AUDIO_SERVICE);int max=audio.getStreamMaxVolume(AudioManager.STREAM_MUSIC);return max==0?0:Math.round(100f*audio.getStreamVolume(AudioManager.STREAM_MUSIC)/max);}@JavascriptInterface public void setVolume(int value){runOnUiThread(()->{AudioManager audio=(AudioManager)getSystemService(AUDIO_SERVICE);int max=audio.getStreamMaxVolume(AudioManager.STREAM_MUSIC);audio.setStreamVolume(AudioManager.STREAM_MUSIC,Math.round(max*Math.max(0,Math.min(100,value))/100f),0);});}@JavascriptInterface public int sleepMinutes(){return playback.sleepMinutes();}@JavascriptInterface public void sleep(int minutes){runOnUiThread(()->playback.sleep(minutes));}@JavascriptInterface public String catalogJson(){return stations.toString();}@JavascriptInterface public String initialStation(){return getIntent().getStringExtra("station")==null?"":getIntent().getStringExtra("station");}@JavascriptInterface public String performanceMode(){return UiSettings.prefs(RadioActivity.this).getString("performanceMode","light");}@JavascriptInterface public String deviceInfo(){try{return DeviceCapabilities.info(RadioActivity.this).toString();}catch(Exception e){return "{}";}}@JavascriptInterface public String settingsJson(){try{return UiSettings.get(RadioActivity.this).toString();}catch(Exception e){return "{}";}}@JavascriptInterface public String favoritesJson(){JSONArray ids=new JSONArray();for(int i=0;i<stations.length();i++){String id=stations.optJSONObject(i).optString("id");if(getSharedPreferences("radio"+(UiSettings.prefs(RadioActivity.this).getString("viewerId","default").equals("default")?"":"@"+UiSettings.prefs(RadioActivity.this).getString("viewerId","default")),0).getBoolean("fav:"+id,false))ids.put(id);}return ids.toString();}@JavascriptInterface public void favorite(String id,boolean value){for(int i=0;i<stations.length();i++)if(stations.optJSONObject(i).optString("id").equals(id))getSharedPreferences("radio"+(UiSettings.prefs(RadioActivity.this).getString("viewerId","default").equals("default")?"":"@"+UiSettings.prefs(RadioActivity.this).getString("viewerId","default")),0).edit().putBoolean("fav:"+id,value).apply();}@JavascriptInterface public void play(String id){runOnUiThread(()->{playback.play(id);});}@JavascriptInterface public void alternate(String id){runOnUiThread(()->startAlternate(id));}@JavascriptInterface public void toggle(){runOnUiThread(()->playback.toggle());}@JavascriptInterface public String playbackJson(){return playback.status().toString();}@JavascriptInterface public void stop(){runOnUiThread(()->{playback.stop();});}@JavascriptInterface public void exit(){runOnUiThread(()->finish());}}
 void key(String key){js("if(window.RadioUI)RadioUI.remote("+JSONObject.quote(key)+")");}
 @Override public void finish(){super.finish();overridePendingTransition(0,0);}
 @Override protected void onResume(){super.onResume();active=this;playback.attach(playbackListener);}@Override public void onBackPressed(){key("RETURN");}@Override protected void onPause(){if(active==this)active=null;playback.detach(playbackListener);super.onPause();}@Override protected void onDestroy(){if(web!=null)web.destroy();super.onDestroy();}
}
